def balanced(s):
    stack = []
    for char in s:
        if char in '([{':
            stack.append(char)
        elif char in ')]}':
            if not stack or {')': '(', '}': '{', ']': '['}[char]:
                return False
        elif char in '([{':
            stack.append(char)
    return not stack

def merge(a,b):
    result = []
    i = j = 0
    while i < len(a) and j < len(b):
        if a[i] < b[j]:
            result.append(a[i])
            i += 1
        else:
            result.append(b[j])
            j += 1
    result.extend(a[i:])
    result.extend(b[j:])
    return result

def to_base(n,b):
    digits = "0123456789abcdef"
    if n == 0:
        return "0"
    result = ""
    while n > 0:
        n, remainder = divmod(n, b)
        result = digits[remainder] + result
    return result
